parameters.jsCode:
const response = $input.item.json;
let raw = "";
try {
  raw = response.content[0].text;
} catch (e) {
  return { json: {
    messages: ["(empty Claude response - check API node)"],
    messages_count: 1,
    notes: "ERROR: could not extract text from Claude API response",
    parse_status: "extract_failed",
    should_send_payment: false,
    payment_amount: 0,
    payment_summary: "",
    break_condition: { hit: false },
    raw_response: JSON.stringify(response),
    customer_phone: $('Build Prompt').item.json.customerPhone,
    customer_name: $('Build Prompt').item.json.customerName,
    user_message: $('Build Prompt').item.json.userMessage,
    conversation_history: $('Build Prompt').item.json.conversationHistory,
    history_count: $('Build Prompt').item.json.historyCount
  } };
}
let cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
let parsed;
let parseStatus = "ok";
try {
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed.messages) || parsed.messages.length === 0) throw new Error("messages array missing or empty");
} catch (e) {
  parsed = { messages: [raw], notes_for_zayn: "(JSON parse failed - Claude returned plain text. Error: " + e.message + ")" };
  parseStatus = "fallback_plain_text";
}
const messages = parsed.messages.slice(0, 4).map(m => String(m));
return { json: {
  messages: messages,
  messages_count: messages.length,
  notes: parsed.notes_for_zayn || "(no notes)",
  break_condition: (parsed && parsed.break_condition && typeof parsed.break_condition.hit === 'boolean')
    ? parsed.break_condition : { hit: false },
  should_send_payment: !!(parsed && parsed.should_send_payment === true),
  payment_amount: (parsed && Number(parsed.payment_amount)) || 0,
  payment_summary: (parsed && typeof parsed.payment_summary === "string")
    ? parsed.payment_summary : "",
  parse_status: parseStatus,
  raw_response: raw,
  customer_phone: $('Build Prompt').item.json.customerPhone,
  customer_name: $('Build Prompt').item.json.customerName,
  user_message: $('Build Prompt').item.json.userMessage,
  conversation_history: $('Build Prompt').item.json.conversationHistory,
  history_count: $('Build Prompt').item.json.historyCount
} };

// feature-header: Customer Facts sits between Parse Response and this
// node, so $input here is the Customer Facts HTTP response. Resolve the
// draft data from whichever parse node actually ran.
let input;
try { input = $('Parse Response').item.json; }
catch (e) { input = $('Parse Lead Response').item.json; }
let customerHeader = '';
try { customerHeader = ($('Customer Facts').item.json || {}).customer_header || ''; }
catch (e) { customerHeader = ''; }
// Nomod: when the payment branch ran, use its message + header
let paymentMessage = null, paymentHeader = '';
try {
  const __pm = $('Build Payment Message').item.json;
  if (__pm && __pm.payment_message) {
    paymentMessage = String(__pm.payment_message);
    paymentHeader = __pm.payment_header || '';
  }
} catch (e) { paymentMessage = null; }
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.pendingQueue)) data.pendingQueue = [];

const id = $now.toMillis().toString() + '_' + Math.random().toString(36).slice(2, 7);
const messages = paymentMessage
  ? [paymentMessage]
  : ((Array.isArray(input.messages) && input.messages.length)
      ? input.messages.map(m => String(m))
      : ['(empty draft)']);
const hc = Number(input.history_count) || 0;

const pending = {
  id: id,
  timestamp: $now.toISO(),
  customer_phone: input.customer_phone,
  customer_name: input.customer_name || '',
  customer_message: input.user_message,
  conversation_history: input.conversation_history || '',
  history_count: hc,
  messages: messages,
  draft_text: messages.join('\n\n'),
  messages_sent_count: 0,
  notes: input.notes,
  telegram_message_id: null,
  telegram_chat_id: 5532831477,
  status: 'pending',
  break_condition: input.break_condition || { hit: false },
  is_lead: !!input.is_lead,
  is_payment: !!paymentMessage   // Nomod: skip the FR-5 improver
};
data.pendingQueue.push(pending);

const preview = messages.length === 1
  ? messages[0]
  : messages.map((m, i) => (i + 1) + '. ' + m).join('\n');
const draftHeader = messages.length === 1 ? '💬 DRAFT:' : ('💬 DRAFT (' + messages.length + ' messages):');
const histLine = hc > 0
  ? ('📜 History: ' + hc + ' prior message' + (hc === 1 ? '' : 's'))
  : '📜 First contact';

let lines;
if (input.is_lead) {
  lines = ['🆕 NEW LEAD — outbound first contact', '📞 ' + pending.customer_phone, '', 'Lead brief (from you):', '"' + pending.customer_message + '"', '', '---', draftHeader, preview, '', '📝 Notes: ' + pending.notes];
} else {
  lines = ['📩 from ' + pending.customer_phone];
  if (customerHeader) {
    lines.push(customerHeader);
  } else {
    if (pending.customer_name) lines.push('👤 ' + pending.customer_name);
    lines.push(histLine);
  }
  lines.push('', 'They said:', '"' + pending.customer_message + '"', '', '---', draftHeader, preview, '', '📝 Notes: ' + pending.notes);
}

if (paymentHeader) lines = [paymentHeader].concat(lines);

const reply_markup = {
  inline_keyboard: [
    [{ text: '✅ Send', callback_data: 'send:' + id }, { text: '✏️ Edit', callback_data: 'edit:' + id }],
    [{ text: '🔁 Regen', callback_data: 'regen:' + id }, { text: '❌ Skip', callback_data: 'skip:' + id }],
    [{ text: '🤖 Auto', callback_data: 'auto:' + id }]
  ]
};
return { json: { telegram_payload: { chat_id: 5532831477, text: lines.join('\n'), reply_markup: reply_markup }, draft_id: id } };

// Save Telegram message_id back to the pending draft for later editing
const tgResponse = $input.item.json;
const messageId = tgResponse.result?.message_id;
const draftId = $('Queue & Format').item.json.draft_id;

const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === draftId);
if (entry && messageId) {
  entry.telegram_message_id = messageId;
}
return { json: { draft_id: draftId, telegram_message_id: messageId, ok: tgResponse.ok } };

// Verify the update is from Zayn (admin)
const body = $input.item.json.body || {};
const adminId = 5532831477;

const fromId = body.callback_query?.from?.id || body.message?.from?.id;

if (fromId !== adminId) {
  // Silently drop — return empty
  return null;
}

// Tag the update type for downstream routing
let updateType = 'unknown';
if (body.callback_query) updateType = 'callback_query';
else if (body.message?.text) updateType = 'message';

return {
  json: {
    update_type: updateType,
    callback_query: body.callback_query || null,
    message: body.message || null,
    raw: body
  }
};

// Parse callback_data and look up the draft.
// Extended in Step 5 (pipeline-review) to handle nudge/snz/inf prefixes
// which carry a customer_id (not a pendingQueue draft id).
const cq = $json.callback_query;
const data = cq.data || '';
const parts = data.split(':');
const action = parts[0] || '';
const second = parts[1] || '';
const third  = parts[2] || '';

// pipeline-review callbacks: nudge:<cid>, snz:<cid>:<dur>, inf:<cid>.
const pipeline = (action === 'nudge' || action === 'snz' || action === 'inf');

const wfData = $getWorkflowStaticData('global');
const queue = wfData.pendingQueue || [];
const draft = pipeline ? null : queue.find(d => d.id === second);

return {
  json: {
    action: action,
    draft_id: pipeline ? null : second,
    customer_id: pipeline ? second : (draft ? draft.customer_id : null),
    snooze_duration: (action === 'snz') ? third : null,
    callback_query_id: cq.id,
    chat_id: cq.message.chat.id,
    message_id: cq.message.message_id,
    draft: draft || null,
    // feedback + pipeline callbacks aren't about a pendingQueue draft —
    // let the existing Draft Exists? IF pass them through.
    draft_found: !!draft
      || (action || '').indexOf('feedback_') === 0
      || pipeline
  }
};

