// Parse regen response, update the existing draft (R3: array shape)
const response = $input.item.json;
let raw = "";
try { raw = response.content[0].text; } catch (e) {
  return { json: { error: "Empty Claude response on regen", raw: JSON.stringify(response) } };
}
let cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed.messages) || !parsed.messages.length) throw new Error("messages missing");
} catch (e) {
  parsed = { messages: [raw], notes_for_zayn: "(parse fail: " + e.message + ")" };
}
const msgs = parsed.messages.slice(0, 4).map(m => String(m));
const draftId = $('Build Regen Prompt').item.json.draft_id;
const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === draftId);
if (entry) {
  entry.messages = msgs;
  entry.draft_text = msgs.join('\n\n');
  entry.notes = parsed.notes_for_zayn || entry.notes;
  entry.messages_sent_count = 0;
}
const preview = msgs.length === 1 ? msgs[0] : msgs.map((m, i) => (i + 1) + '. ' + m).join('\n');
return { json: {
  draft_id: draftId,
  new_preview: preview,
  new_notes: parsed.notes_for_zayn || '(no notes)',
  customer_phone: entry ? entry.customer_phone : 'unknown',
  customer_name: entry ? entry.customer_name : '',
  customer_message: entry ? entry.customer_message : ''
} };

// route an admin Telegram message: /lead, /send, edit-feedback, reply, or ack
const msg = $input.item.json.message || {};
const text = (msg.text || '').trim();
const adminChatId = (msg.chat && msg.chat.id) ? msg.chat.id : 5532831477;
const data = $getWorkflowStaticData('global');
const queue = data.pendingQueue || [];

// (C) /lead <free-form> -> create an outbound first-contact draft (FR-2)
if (text.toLowerCase().indexOf('/lead') === 0) {
  const leadText = text.slice(5).trim();
  const cand = leadText.match(/[+\d][\d\s().\-]{7,}\d/g) || [];
  let phone = '';
  for (const c of cand) {
    const d = c.replace(/[^\d]/g, '');
    if (d.length >= 9 && d.length > phone.length) phone = d;
  }
  if (!phone) {
    return { json: { action: 'ack', admin_chat_id: adminChatId,
      ack_text: "⚠️ Couldn't find a phone number in that lead. Try:  /lead <name> <phone> <details>" } };
  }
  let norm = phone.replace(/^00/, '');
  if (norm.length === 10 && norm[0] === '0') norm = '971' + norm.slice(1);
  else if (norm.length === 9 && norm[0] === '5') norm = '971' + norm;
  return { json: { action: 'new_lead', lead_phone: norm + '@c.us',
    lead_text: leadText, admin_chat_id: adminChatId } };
}

// (B) /send <chatId> <message>
if (text.toLowerCase().indexOf('/send ') === 0) {
  const rest = text.slice(6).trim();
  const sp = rest.indexOf(' ');
  if (sp < 1) {
    return { json: { action: 'ack', admin_chat_id: adminChatId,
      ack_text: 'Usage:  /send <chatId> <message>' } };
  }
  return { json: { action: 'send_to_customer', origin: 'slash',
    target_chatId: rest.slice(0, sp).trim(), final_text: rest.slice(sp + 1).trim(),
    admin_chat_id: adminChatId } };
}

// (E) /auto, /manual — switch a conversation's autonomous mode (FR-4)
{
  const low = text.toLowerCase();
  if (low === '/auto' || low === '/manual' || low === '/manual all') {
    let d2 = null;
    const r2 = msg.reply_to_message;
    if (r2 && r2.message_id) {
      for (let _i = queue.length - 1; _i >= 0; _i--) {
        if (queue[_i].telegram_message_id === r2.message_id) { d2 = queue[_i]; break; }
      }
    }
    if (low === '/auto') {
      if (!d2) {
        return { json: { action: 'ack', admin_chat_id: adminChatId,
          ack_text: '⚠️ reply to a customer draft card with /auto to hand that conversation to autonomous mode.' } };
      }
      return { json: { action: 'mode_cmd', mode_target: d2.customer_phone,
        mode: 'autonomous', admin_chat_id: adminChatId } };
    }
    if (low === '/manual all' || !d2) {
      return { json: { action: 'mode_cmd', mode_target: '__ALL__',
        mode: 'approval', admin_chat_id: adminChatId } };
    }
    return { json: { action: 'mode_cmd', mode_target: d2.customer_phone,
      mode: 'approval', admin_chat_id: adminChatId } };
  }
}

// (F) /caps — report autonomous-mode safety-cap status (BUG-2)
if (text.toLowerCase() === '/caps') {
  return { json: { action: 'caps_cmd', admin_chat_id: adminChatId } };
}

// (PR) /review [filter] — Pipeline Review report (Step 5 of pipeline-review)
{
  const lo = text.toLowerCase();
  if (lo === '/review' || lo.indexOf('/review ') === 0) {
    const arg = text.slice(7).trim().toLowerCase();
    const allowed = ['all','hot','warm','cold'];
    const filt = allowed.indexOf(arg) >= 0 ? arg : 'all';
    return { json: { action: 'review_cmd', filter: filt,
      admin_chat_id: adminChatId } };
  }
}

// (PI) /info <name-or-phone> — single-lead context dump
{
  const lo = text.toLowerCase();
  if (lo === '/info' || lo.indexOf('/info ') === 0) {
    const arg = text.slice(5).trim();
    if (!arg) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  /info <name or phone>' } };
    }
    // @lid customer_ids contain '@'; everything else is treated as a name.
    const isId = arg.indexOf('@') >= 0;
    return { json: { action: 'info_cmd', info_query: arg,
      info_query_kind: isId ? 'customer_id' : 'name',
      admin_chat_id: adminChatId } };
  }
}

// (PL) /label <name-or-phone> <LABEL> — manual label override
{
  const lo = text.toLowerCase();
  if (lo === '/label' || lo.indexOf('/label ') === 0) {
    const parts = text.slice(7).trim().split(/\s+/);
    if (parts.length < 2) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  /label <name or phone> <LABEL>\n'
          + 'LABELS: NEW, WARM, HOT, NEEDS_ATTENTION, COLD,\n'
          + '        PAUSED_SPAM, PAUSED_B2B, PAUSED_PERSONAL' } };
    }
    const label = parts[parts.length - 1].toUpperCase();
    const who = parts.slice(0, -1).join(' ');
    const isId = who.indexOf('@') >= 0;
    return { json: { action: 'label_cmd', label_query: who,
      label_query_kind: isId ? 'customer_id' : 'name',
      label_value: label, admin_chat_id: adminChatId } };
  }
}

// (PS) /snooze <name-or-phone> <dur> — snooze a customer (no label change)
{
  const lo = text.toLowerCase();
  if (lo === '/snooze' || lo.indexOf('/snooze ') === 0) {
    const parts = text.slice(8).trim().split(/\s+/);
    if (parts.length < 2) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  /snooze <name or phone> <duration>\n'
          + 'examples:  /snooze Mark 4h    /snooze +971... 2d' } };
    }
    const duration = parts[parts.length - 1].toLowerCase();
    const who = parts.slice(0, -1).join(' ');
    const isId = who.indexOf('@') >= 0;
    return { json: { action: 'snooze_cmd', snooze_query: who,
      snooze_query_kind: isId ? 'customer_id' : 'name',
      snooze_duration: duration, admin_chat_id: adminChatId } };
  }
}

// (G) /feedback <text> — operator behavioural feedback (classify +
//     confirm + store in customer_notes / behavior_rules)
{
  const lo = text.toLowerCase();
  if (lo === '/feedback' || lo.indexOf('/feedback ') === 0) {
    const fb = text.slice(9).trim();
    if (!fb) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  /feedback <text>\n'
          + 'examples:\n'
          + '  /feedback never offer phone calls\n'
          + '  /feedback Mark booked Aurora last March, mention it\n'
          + '  /feedback offer fine dining first to family groups'
      } };
    }
    return { json: { action: 'feedback_cmd', feedback_text: fb,
      admin_chat_id: adminChatId } };
  }
}

// (D) /rules, /approverule <id>, /discardrule <id> — rule review (FR-5)
{
  const low = text.toLowerCase();
  if (low === '/rules' || low.indexOf('/rules ') === 0) {
    return { json: { action: 'rules_cmd', rules_action: 'list', rule_id: null,
      admin_chat_id: adminChatId } };
  }
  if (low.indexOf('/approverule ') === 0 || low.indexOf('/discardrule ') === 0) {
    const isApprove = low.indexOf('/approverule ') === 0;
    const rid = (text.split(/\s+/)[1] || '').trim();
    if (!/^\d+$/.test(rid)) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  ' + (isApprove ? '/approverule' : '/discardrule')
          + ' <rule id number>' } };
    }
    return { json: { action: 'rules_cmd',
      rules_action: isApprove ? 'activate' : 'discard', rid_text: rid,
      rule_id: rid, admin_chat_id: adminChatId } };
  }
}

// (edit) a draft is awaiting feedback -> refine it, do NOT send (FR-1)
const awaiting = queue.find(x => x.status === 'awaiting_edit');
if (awaiting && text) {
  awaiting.status = 'pending';          // release the edit lock; refine redraws
  return { json: { action: 'refine', draft_id: awaiting.id, feedback: text,
    admin_chat_id: adminChatId } };
}

// (A) reply to a draft card — DEFAULT: feedback to Claude (refine). Only an
//     explicit "send this: X" sends X verbatim; "ask this: X" -> refine to ask X.
const r = msg.reply_to_message;
if (r && r.message_id) {
  // newest-match: telegram message_ids collide across bot/session resets
  let d = null;
  for (let _i = queue.length - 1; _i >= 0; _i--) {
    if (queue[_i].telegram_message_id === r.message_id) { d = queue[_i]; break; }
  }
  if (d && text) {
    const lo = text.toLowerCase();
    if (lo.indexOf('send this:') === 0) {
      // explicit directive — send the operator's text verbatim
      return { json: { action: 'send_to_customer', origin: 'reply',
        target_chatId: d.customer_phone, final_text: text.slice(10).trim(),
        draft_id: d.id, admin_chat_id: adminChatId } };
    }
    // everything else is FEEDBACK FOR CLAUDE — refine the draft, never auto-send
